// Secure Express Application with Error Handling, Input Validation, and Security Best Practices

require('dotenv').config(); // Load environment variables
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { check, validationResult } = require('express-validator');
const cors = require('cors');
const logger = require('./logger'); // Assume a simple logger (e.g., Winston)

const app = express();

// ======================
// Security Middleware
// ======================
app.use(helmet()); // Sets secure HTTP headers
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') || '*' })); // Restrict CORS
app.use(express.json({ limit: '10kb' })); // Prevent large JSON payloads

// ======================
// Rate Limiting
// ======================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// ======================
// Input Validation Middleware
// ======================
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`Validation failed: ${JSON.stringify(errors.array())}`);
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  };
};

// ======================
// Routes
// ======================
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
  });
});

app.get(
  '/users',
  validate([
    check('id').optional().isInt().withMessage('ID must be an integer'),
    check('email').optional().isEmail().withMessage('Invalid email'),
  ]),
  (req, res, next) => {
    try {
      const { id, email } = req.query;
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter users if query parameters are provided
      if (id) {
        users = users.filter(user => user.id === parseInt(id));
      }
      if (email) {
        users = users.filter(user => user.email === email);
      }

      res.json(users);
    } catch (err) {
      logger.error(`Error in /users: ${err.message}`);
      next(err); // Pass to error handler
    }
  }
);

// ======================
// 404 Handler
// ======================
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// ======================
// Error Handling Middleware
// ======================
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.stack}`);
  res.status(500).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error',
  });
});

// ======================
// Start Server
// ======================
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

